class Solution {
  private static int[] zf(char[] s) {
    int[] z = new int[s.length];
    for (int i = 1, l = 0, r = 0; i < s.length; i++) {
      if (i < r) z[i] = Math.min(r - i, z[i - l]);
      while (i + z[i] < s.length && s[z[i]] == s[i + z[i]]) z[i]++;
      if (i + z[i] > r) {
        l = i;
        r = i + z[i];
      }
    }
    return z;
  }

  public int minStartingIndex(String s, String pattern) {
    int n = s.length(), m = pattern.length();
    char[] a = new char[m + 1 + n], b = new char[m + 1 + n];
    for (int i = 0; i < m; i++) {
      a[i] = pattern.charAt(i);
      b[i] = pattern.charAt(m - 1 - i);
    }
    a[m] = b[m] = '{';
    for (int i = 0; i < n; i++) {
      a[m + 1 + i] = s.charAt(i);
      b[m + 1 + i] = s.charAt(n - 1 - i);
    }
    int[] pre = zf(a), suf = zf(b);
    for (int i = 0; i + m <= n; i++) {
      if (pre[m + 1 + i] + suf[m + 1 + n - i - m] >= m - 1) return i;
    }
    return -1;
  }
}
